BEGIN
 RETURN (SELECT COUNT(*) FROM tbd_products_categories pc JOIN tb_products p ON p.ID=pc.product_ID WHERE pc.category_ID=p_category_id AND pc.status=b'1' AND p.status=b'1');
END

BEGIN
 IF NOT EXISTS(SELECT 1 FROM mysql.role_edges WHERE TO_USER=SUBSTRING_INDEX(USER(),'@',1) AND TO_HOST='%' AND FROM_USER IN ('superadmin','admin')) THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Acceso denegado: rol no autorizado';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM tb_products WHERE ID=p_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='El registro no existe'; END IF;
 UPDATE tb_products SET status=1 WHERE ID=p_id;
END

